function gc_uuid():string {$h=bin2hex(random_bytes(16));return substr($h,0,8).'-'.substr($h,8,4).'-4'.substr($h,13,3).'-'.dechex((hexdec($h[16])&3)|8).substr($h,17,3).'-'.substr($h,20);}
function gc_settings():array {$g=cfg()['giftcards']??[];foreach(rows('SELECT name,value_json FROM pg_runtime_settings') as $r)if(in_array($r['name'],['sales_enabled','legal_approved','legal_effective_date','payment_instructions','agent_signature_path','agent_signature_sha256','agent_signature_approved'],true))$g[$r['name']]=json_decode($r['value_json'],true,16,JSON_THROW_ON_ERROR);return $g;}
function pina_gc_enabled():void {if(!(gc_settings()['enabled']??false))throw new ApiError('Новая карточная программа пока не открыта',503);}
function gc_key():string {$k=base64_decode(gc_settings()['encryption_key']??'',true);if($k===false||strlen($k)!==32)throw new RuntimeException('GIFTCARDS_ENCRYPTION_NOT_CONFIGURED');return $k;}
function gc_encrypt(string $plain):string {$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt($plain,'aes-256-gcm',gc_key(),OPENSSL_RAW_DATA,$iv,$tag,'pina-giftcards-v1',16);if($cipher===false)throw new RuntimeException('ENCRYPTION_FAILED');return base64_encode($iv.$tag.$cipher);}
function gc_decrypt(string $value):string {$b=base64_decode($value,true);if($b===false||strlen($b)<29)throw new RuntimeException('INVALID_CIPHERTEXT');$s=openssl_decrypt(substr($b,28),'aes-256-gcm',gc_key(),OPENSSL_RAW_DATA,substr($b,0,12),substr($b,12,16),'pina-giftcards-v1');if($s===false)throw new RuntimeException('DECRYPTION_FAILED');return $s;}
function gc_code_hash(string $code):string {return hash_hmac('sha256',$code,gc_key());}
function gc_provider(?string $issuer=null):VdarClient {if(PHP_SAPI==='cli'&&defined('PINA_LIBRARY_ONLY')&&isset($GLOBALS['gc_test_provider']))return ($GLOBALS['gc_test_provider'])($issuer);$c=gc_credentials($issuer??'pina');return new VdarClient((string)($c['api_key']??''),(string)($c['site_id']??''));}
function gc_offer():array {$f=__DIR__.'/giftcards-offer.json';$d=json_decode(file_get_contents($f),true,512,JSON_THROW_ON_ERROR);$effective=gc_settings()['legal_effective_date']??'';if(gc_settings()['legal_approved']??false){if(!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/D',$effective,$m)||!checkdate((int)$m[2],(int)$m[3],(int)$m[1]))throw new RuntimeException('LEGAL_EFFECTIVE_DATE_REQUIRED');foreach($d['content'] as &$item)if(isset($item['text']))$item['text']=str_replace('[дата размещения на сайте]',gmdate('d.m.Y',strtotime($effective)),$item['text']);unset($item);$d['version'].='-'.$effective;}$hash=hash('sha256',json_encode($d,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE));return ['version'=>$d['version'],'hash'=>$hash,'content'=>$d['content']];}
function gc_verified(array $c):void {if(!one('SELECT client_id FROM pg_profiles WHERE client_id=? AND email_verified_at IS NOT NULL',[$c['id']]))throw new ApiError('Подтвердите email по ссылке из письма',403);}
function gc_member(array $c,string $issuer,array $roles=['owner','operator','accountant']):array {$r=one('SELECT m.*,i.status,i.contract_status,i.vdar_site_id,i.recipient_login,i.program_json,i.company_json,i.name FROM pg_issuer_members m JOIN pg_issuers i ON i.id=m.issuer_id WHERE m.client_id=? AND m.issuer_id=?',[$c['id'],$issuer]);if(!$r||!in_array($r['role'],$roles,true))throw new ApiError('Недостаточно прав для этой компании',403);return $r;}
function gc_card(string $id):array {$c=one('SELECT c.*,o.client_id,o.issuer_id,o.payment_status,o.snapshot_json FROM pg_cards c JOIN pg_orders o ON o.id=c.order_id WHERE c.id=?',[$id]);if(!$c)throw new ApiError('Карта не найдена',404);return $c;}
function gc_owned_card(array $actor,string $id):array {$c=gc_card($id);if((int)$c['client_id']!==(int)$actor['id'])throw new ApiError('Карта не найдена',404);return $c;}
function gc_public_issuer(array $i):array {$p=json_decode($i['program_json'],true,512,JSON_THROW_ON_ERROR);$co=json_decode($i['company_json'],true,512,JSON_THROW_ON_ERROR);return ['id'=>$i['id'],'name'=>$i['name'],'country'=>$i['country'],'company'=>array_intersect_key($co,array_flip(['name','reg','tax','address','email','phone'])),'program'=>$p];}
function gc_catalog():array {return array_map('gc_public_issuer',rows("SELECT * FROM pg_issuers WHERE status='active' AND contract_status='approved' ORDER BY name"));}
function gc_order_json(array $o):array {$o['snapshot']=json_decode($o['snapshot_json'],true);unset($o['snapshot_json'],$o['request_hash']);$o['cards']=rows('SELECT id,nominal_minor,currency,issuance_status,redemption_status,refund_status,provided_at,expires_at FROM pg_cards WHERE order_id=? ORDER BY created_at,id',[$o['id']]);return $o;}
function gc_enqueue(string $id,string $kind,?string $activation=null):string {$existing=one('SELECT id FROM pg_commands WHERE card_id=? AND kind=?',[$id,$kind]);if($existing)return $existing['id'];$command=gc_uuid();query('INSERT INTO pg_commands(id,card_id,activation_id,kind,created_at) VALUES(?,?,?,?,?)',[$command,$id,$activation,$kind,now()]);return $command;}
function gc_card_mail(string $cardId,string $subject,string $body):void {$r=one('SELECT p.email,o.id FROM pg_cards c JOIN pg_orders o ON o.id=c.order_id JOIN pm_clients p ON p.id=o.client_id WHERE c.id=?',[$cardId]);if(!$r)return;query('INSERT INTO pm_mail_queue(recipient,subject,body,available_at,created_at) VALUES(?,?,?,?,?)',[$r['email'],$subject,$body."\nЗаказ № ".$r['id']."\nЛичный кабинет: ".rtrim(cfg()['base_url'],'/').'/giftcards/#/account/cards',now(),now()]);}
function gc_accept_offer(array $d):array {$o=gc_offer();if(($d['accepted']??false)!==true||($d['offerVersion']??'')!==$o['version'])throw new ApiError('Ознакомьтесь с актуальной офертой и подтвердите согласие');query('INSERT IGNORE INTO pg_legal_versions(hash,version,document_json,created_at) VALUES(?,?,?,?)',[$o['hash'],$o['version'],json_encode($o,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE),now()]);return $o;}
