 if($route==='merchant/settlements/ack/'&&$post){$id=txt($d,'settlementId',36);$reference=txt($d,'bankReference',150);$amount=minor($d['amount']??'',100000000000);return transact(function()use($actor,$id,$reference,$amount){$s=one('SELECT * FROM pg_settlements WHERE id=? FOR UPDATE',[$id]);if(!$s)throw new ApiError('Расчёт не найден',404);gc_member($actor,$s['issuer_id'],['owner','accountant']);if($s['received_at']){if((int)$s['received_minor']!==$amount||$s['received_reference']!==$reference)throw new ApiError('Подтверждение уже зарегистрировано с другими данными',409);return ['status'=>'received'];}if($s['status']!=='bank_credited'||(int)$s['net_minor']!==$amount)throw new ApiError('Сверьте реестр и фактически полученную сумму; при расхождении обратитесь в поддержку',409);query("UPDATE pg_settlements SET status='received',received_reference=?,received_minor=?,received_by=?,received_at=? WHERE id=?",[$reference,$amount,$actor['id'],now(),$id]);query('INSERT INTO pg_balance_returns(id,settlement_id,created_at) VALUES(?,?,?)',[gc_uuid(),$id,now()]);audit((int)$actor['id'],'gift_settlement_received',$id);return ['status'=>'received','balanceReturn'=>'manual_review'];});}
