 if($route==='bank-confirm/'){return transact(function()use($d,$actor){$id=(int)($d['orderId']??0);$o=one('SELECT * FROM pg_orders WHERE id=? FOR UPDATE',[$id]);if(!$o)throw new ApiError('Заказ не найден',404);$ref=txt($d,'bankReference',150);if(one('SELECT id FROM pg_bank_events WHERE order_id=? LIMIT 1',[$id]))throw new ApiError('У заказа есть отдельные банковские поступления. Используйте раздел Поступления.',409);$amount=minor($d['amount']??'',100000000000);if($amount!==(int)$o['total_minor'])throw new ApiError('Сумма не соответствует заказу');$old=one('SELECT * FROM pg_bank_receipts WHERE order_id=?',[$id]);if($old){if($old['reference']!==$ref||(int)$old['amount_minor']!==$amount)throw new ApiError('Уже есть другое подтверждение',409);return ['status'=>'confirmed'];}if(one('SELECT number FROM pm_operations WHERE bank_reference=?',[$ref]))throw new ApiError('Это поступление уже учтено в прежнем сервисе',409);query('INSERT INTO pg_bank_references(reference,event_kind,object_id,created_at) VALUES(?,?,?,?)',[$ref,'gift_payment',(string)$id,now()]);query('INSERT INTO pg_bank_receipts(order_id,reference,amount_minor,confirmed_by,confirmed_at) VALUES(?,?,?,?,?)',[$id,$ref,$amount,$actor['id'],now()]);query("UPDATE pg_orders SET payment_status='confirmed',updated_at=? WHERE id=?",[now(),$id]);audit((int)$actor['id'],'gift_bank_confirmed',$id,['bankReference'=>$ref]);return ['status'=>'confirmed'];});}
 if($route==='issuer-approve/'){return transact(function()use($d,$actor){$id=txt($d,'issuerId',36);$i=one('SELECT * FROM pg_issuers WHERE id=? FOR UPDATE',[$id]);if(!$i)throw new ApiError('Компания не найдена');$program=$d['program']??null;if(!is_array($program)||empty($program['nominals'])||empty($program['rules'])||empty($program['expires_seconds'])||(int)$program['expires_seconds']<1||(int)$program['expires_seconds']>31536000)throw new ApiError('Согласуйте полные условия программы');if(!filter_var($program['rules'],FILTER_VALIDATE_URL)||parse_url($program['rules'],PHP_URL_SCHEME)!=='https'||($program['partial_redemption']??false)!==false)throw new ApiError('Проверьте HTTPS-ссылку и полное погашение карты');foreach($program['nominals'] as $n)if(!is_int($n)||!in_array($n,[1000000,5000000,10000000,50000000,100000000,500000000],true))throw new ApiError('Недопустимый номинал программы');foreach(['issue_deadline','request_deadline','use_country','redemption','refund'] as $field)if(empty($program[$field]))throw new ApiError('Не заполнено условие '.$field);$site=txt($d,'siteId',36);$login=txt($d,'recipientLogin',140);$configured=gc_credentials($id);if(($configured['site_id']??'')!==$site||($configured['recipient_login']??'')!==$login||empty($configured['api_key']))throw new ApiError('Настройте ключ и торговую точку компании на сервере');if(!one("SELECT id FROM pg_documents WHERE issuer_id=? AND kind='signed_contract' AND status='approved' AND version=?",[$id,$i['contract_version']]))throw new ApiError('Проверьте подписанный договор');if(!(gc_settings()['agent_signature_approved']??false))throw new ApiError('Подпись Pina Market ещё не утверждена');query("UPDATE pg_issuers SET status='active',contract_status='approved',program_json=?,vdar_site_id=?,recipient_login=?,updated_at=? WHERE id=?",[json_encode($program,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE),$site,$login,now(),$id]);audit((int)$actor['id'],'gift_issuer_approved',$id);return ['status'=>'active'];});}
 if($route==='document-approve/'){return transact(function()use($d,$actor){$id=txt($d,'documentId',36);$doc=one('SELECT * FROM pg_documents WHERE id=? FOR UPDATE',[$id]);if(!$doc||$doc['kind']!=='signed_contract')throw new ApiError('Документ не найден');$i=one('SELECT contract_version,contract_status FROM pg_issuers WHERE id=? FOR UPDATE',[$doc['issuer_id']]);if(($d['signaturesVerified']??false)!==true||$i['contract_version']!==$doc['version']||!one("SELECT id FROM pg_documents WHERE issuer_id=? AND kind='generated_contract' AND version=? AND status='agent_signed'",[$doc['issuer_id'],$doc['version']]))throw new ApiError('Нужно проверить подписи и соответствие действующей редакции');query("UPDATE pg_documents SET status='approved' WHERE id=?",[$id]);audit((int)$actor['id'],'gift_document_approved',$id,['sha256'=>$doc['sha256']]);return ['status'=>'approved'];});}
 if($route==='balance-reconcile/'){return transact(function()use($d,$actor){$id=txt($d,'settlementId',36);$r=one('SELECT b.*,s.status AS settlement_status FROM pg_balance_returns b JOIN pg_settlements s ON s.id=b.settlement_id WHERE b.settlement_id=? FOR UPDATE',[$id]);if(!$r||$r['settlement_status']!=='received')throw new ApiError('Сначала поставщик должен подтвердить банковское поступление',409);$note=txt($d,'note',3000);$ref=txt($d,'providerReference',200);if(($d['balanceVerified']??false)!==true)throw new ApiError('Подтвердите ручную сверку остатка платформы');if($r['status']==='reconciled')return ['status'=>'reconciled'];query("UPDATE pg_balance_returns SET status='reconciled',reconciliation_note=?,provider_reference=?,verified_by=?,reviewed_at=? WHERE settlement_id=?",[$note,$ref,$actor['id'],now(),$id]);audit((int)$actor['id'],'gift_balance_manually_reconciled',$id,['reference'=>$ref]);return ['status'=>'reconciled','transferPerformed'=>false];});}
 if($route==='retry-safe-command/'){return transact(function()use($d,$actor){$id=txt($d,'commandId',36);$r=one('SELECT * FROM pg_commands WHERE id=? FOR UPDATE',[$id]);if(!$r||$r['status']!=='failed'||!in_array($r['error_code'],['INSUFFICIENT_BALANCE','INVALID_AMOUNT','INVALID_CURRENCY','CODE_GENERATION_DISABLED','SITE_NOT_FOUND','DEFAULT_SITE_NOT_FOUND','INVALID_RECIPIENT','REFUND_PENDING'],true))throw new ApiError('Повторный запрос небезопасен: сначала требуется сверка исходной операции',409);$c=gc_card($r['card_id']);if($c['refund_status']!=='none'||$c['payment_status']!=='confirmed'||$r['kind']==='cancel')throw new ApiError('Повтор недоступен для текущего состояния карты',409);query("UPDATE pg_commands SET status='queued',claimed_at=NULL,error_code=NULL WHERE id=?",[$id]);$column=$r['kind']==='issue'?'issuance_status':'redemption_status';query('UPDATE pg_cards SET '.$column.'=?,updated_at=? WHERE id=?',['pending',now(),$c['id']]);if($r['activation_id'])query("UPDATE pg_activations SET status='pending' WHERE id=?",[$r['activation_id']]);audit((int)$actor['id'],'gift_safe_retry_authorised',$id);return ['status'=>'queued'];});}
 if($route==='settlement-prepare/'){return gc_prepare_settlement($d,$actor);}
 if($route==='settlement-bank-credit/'){return transact(function()use($d,$actor){$id=txt($d,'settlementId',36);$s=one('SELECT * FROM pg_settlements WHERE id=? FOR UPDATE',[$id]);if(!$s)throw new ApiError('Расчёт не найден');$ref=txt($d,'bankReference',150);if(!in_array($s['status'],['prepared','sent'],true)){if($s['bank_reference']===$ref)return ['status'=>$s['status']];throw new ApiError('Расчёт уже изменён',409);}if(($d['creditedVerified']??false)!==true)throw new ApiError('Подтвердите проверку зачисления банком получателя');query('INSERT INTO pg_bank_references(reference,event_kind,object_id,created_at) VALUES(?,?,?,?)',[$ref,'issuer_settlement',$id,now()]);query("UPDATE pg_settlements SET status='bank_credited',bank_reference=?,bank_credited_at=? WHERE id=?",[$ref,now(),$id]);audit((int)$actor['id'],'gift_settlement_bank_credit',$id);return ['status'=>'bank_credited'];});}
 if($route==='refund-cancel-code/'){return transact(function()use($d,$actor){$id=txt($d,'cardId',36);one('SELECT id FROM pg_cards WHERE id=? FOR UPDATE',[$id]);$c=gc_card($id);if(!in_array($c['refund_status'],['requested','review','approved','awaiting_issuer'],true)||$c['redemption_status']!=='not_redeemed')throw new ApiError('Нужна отдельная проверка возврата после погашения',409);if($c['issuance_status']==='not_issued'){audit((int)$actor['id'],'gift_unissued_card_cancelled',$id);query("UPDATE pg_cards SET issuance_status='cancelled',updated_at=? WHERE id=?",[now(),$id]);return ['status'=>'cancelled'];}if($c['issuance_status']!=='issued')throw new ApiError('Сначала уточните результат выпуска',409);$command=gc_enqueue($id,'cancel');audit((int)$actor['id'],'gift_refund_cancel_queued',$id);return ['commandId'=>$command];});}
 if($route==='refund-paid/'){return transact(function()use($d,$actor){$id=txt($d,'refundId',36);$r=one('SELECT * FROM pg_refunds WHERE id=? FOR UPDATE',[$id]);if(!$r)throw new ApiError('Обращение не найдено');$c=gc_card($r['card_id']);if($r['status']==='paid')return ['status'=>'paid'];$ref=txt($d,'bankReference',150);$amount=minor($d['amount']??'',100000000000);if($amount!==(int)$c['nominal_minor']||!in_array($c['issuance_status'],['cancelled','not_issued'],true)||$c['redemption_status']!=='not_redeemed')throw new ApiError('Для этой ситуации требуется отдельное решение по основной покупке',409);query('INSERT INTO pg_bank_references(reference,event_kind,object_id,created_at) VALUES(?,?,?,?)',[$ref,'gift_refund',$id,now()]);query("UPDATE pg_refunds SET status='paid',amount_minor=?,bank_reference=?,paid_at=? WHERE id=?",[$amount,$ref,now(),$id]);query("UPDATE pg_cards SET refund_status='paid',issuance_status='cancelled',updated_at=? WHERE id=?",[now(),$c['id']]);audit((int)$actor['id'],'gift_refund_paid',$id);return ['status'=>'paid'];});}
