function gc_prepare_settlement(array $d,array $actor):array {return gc_atomic(function()use($d,$actor){$issuer=txt($d,'issuerId',36);$key=request_key($d);$old=one('SELECT * FROM pg_settlements WHERE request_key=?',[$key]);if($old){$stored=array_column(rows('SELECT activation_id FROM pg_settlement_items WHERE settlement_id=? ORDER BY activation_id',[$old['id']]),'activation_id');$incoming=$d['activationIds']??[];if(!is_array($incoming))throw new ApiError('Проверьте состав реестра');$incoming=array_values(array_unique($incoming));sort($incoming);if($old['issuer_id']!==$issuer||$stored!==$incoming)throw new ApiError('Ключ другого расчёта или состава реестра',409);return $old;}if(!one("SELECT id FROM pg_issuers WHERE id=? AND status IN ('active','paused') FOR UPDATE",[$issuer]))throw new ApiError('Компания недоступна');$ids=$d['activationIds']??[];if(!is_array($ids)||!count($ids)||count($ids)>100)throw new ApiError('Выберите от 1 до 100 операций');$ids=array_values(array_unique($ids));sort($ids);$gross=0;foreach($ids as $id){if(!is_string($id))throw new ApiError('Некорректная операция');$r=one('SELECT a.*,c.refund_status FROM pg_activations a JOIN pg_cards c ON c.id=a.card_id WHERE a.id=? FOR UPDATE',[$id]);if(!$r||$r['issuer_id']!==$issuer||$r['status']!=='confirmed'||$r['refund_status']!=='none'||one('SELECT settlement_id FROM pg_settlement_locks WHERE activation_id=?',[$id]))throw new ApiError('Состав реестра изменился. Обновите данные.',409);$gross+=(int)$r['nominal_minor'];}$fee=static fn(int $bps):int=>intdiv($gross*$bps+5000,10000);$agent=$fee(10);$control=$fee(20);$transfer=$fee(60);$id=gc_uuid();query('INSERT INTO pg_settlements(id,issuer_id,request_key,gross_minor,agent_fee_minor,control_fee_minor,transfer_fee_minor,net_minor,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)',[$id,$issuer,$key,$gross,$agent,$control,$transfer,$gross-$agent-$control-$transfer,$actor['id'],now()]);foreach($ids as $activation){query('INSERT INTO pg_settlement_items(settlement_id,activation_id) VALUES(?,?)',[$id,$activation]);query('INSERT INTO pg_settlement_locks(activation_id,settlement_id) VALUES(?,?)',[$activation,$id]);}audit((int)$actor['id'],'gift_settlement_prepared',$id);return one('SELECT * FROM pg_settlements WHERE id=?',[$id]);});}
